import "server-only";
import { createAdminClient } from "@/lib/supabase/admin";
import { sendPush } from "@/lib/push/webpush";
import { vapidKeys } from "@/lib/push/config";
import { isAiConfigured } from "./client";
import { generateDigest } from "./digest";

export interface DigestDispatchResult {
  /** Pro subscribers due for a digest this run. */
  scanned: number;
  /** Digests generated by the AI. */
  digests: number;
  /** Push messages delivered. */
  sent: number;
  /** Subscribers skipped — no recent notes, or no push subscription. */
  skipped: number;
  /** Dead push subscriptions pruned. */
  removed: number;
  failed: number;
}

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;
// A digest is due once the gap since the last one exceeds this — slightly
// under a week so a weekly cron that drifts a little still fires.
const MIN_GAP_MS = 6 * 24 * 60 * 60 * 1000;

/**
 * Generate and push a weekly AI digest to every Pro subscriber with notes from
 * the past week. Triggered by the same external cron as the reminder
 * dispatcher (see app/api/ai/digest). Needs the Supabase service-role key, an
 * Anthropic key, and VAPID keys; throws clearly if any are missing.
 */
export async function dispatchWeeklyDigests(
  now: Date = new Date(),
): Promise<DigestDispatchResult> {
  const result: DigestDispatchResult = {
    scanned: 0,
    digests: 0,
    sent: 0,
    skipped: 0,
    removed: 0,
    failed: 0,
  };

  if (!isAiConfigured()) throw new Error("ANTHROPIC_API_KEY not configured");
  const keys = vapidKeys();
  if (!keys) throw new Error("VAPID keys not configured (VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY)");

  const supabase = createAdminClient();
  const nowIso = now.toISOString();
  const gapCutoff = new Date(now.getTime() - MIN_GAP_MS).toISOString();
  const weekAgo = new Date(now.getTime() - WEEK_MS).toISOString();

  const { data: proSubs } = await supabase
    .from("subscriptions")
    .select("user_id, last_digest_at")
    .eq("plan", "pro")
    .in("status", ["active", "trialing"])
    .limit(500);

  // ISO 8601 timestamps sort lexically, so a string compare is correct here.
  const due = (proSubs ?? []).filter(
    (s) => !s.last_digest_at || s.last_digest_at < gapCutoff,
  );
  result.scanned = due.length;

  for (const sub of due) {
    // Mark processed up front so a mid-run crash can't cause a re-send storm.
    await supabase
      .from("subscriptions")
      .update({ last_digest_at: nowIso })
      .eq("user_id", sub.user_id);

    const { data: notes } = await supabase
      .from("notes")
      .select("content_md, created_at")
      .eq("user_id", sub.user_id)
      .gte("created_at", weekAgo)
      .is("archived_at", null)
      .order("created_at", { ascending: false })
      .limit(200);
    if (!notes || notes.length === 0) {
      result.skipped += 1;
      continue;
    }

    const { data: pushSubs } = await supabase
      .from("push_subscriptions")
      .select("id, endpoint, p256dh, auth")
      .eq("user_id", sub.user_id);
    if (!pushSubs || pushSubs.length === 0) {
      result.skipped += 1;
      continue;
    }

    let digest;
    try {
      digest = await generateDigest(notes);
      result.digests += 1;
    } catch {
      result.failed += 1;
      continue;
    }

    const payload = JSON.stringify({
      kind: "digest",
      id: `digest-${nowIso.slice(0, 10)}`,
      title: digest.headline,
      body: digest.body,
      url: "/notes",
    });

    for (const ps of pushSubs) {
      try {
        const r = await sendPush(
          { endpoint: ps.endpoint, p256dh: ps.p256dh, auth: ps.auth },
          payload,
          keys,
        );
        if (r.ok) {
          result.sent += 1;
        } else if (r.gone) {
          result.removed += 1;
          await supabase.from("push_subscriptions").delete().eq("id", ps.id);
        } else {
          result.failed += 1;
        }
      } catch {
        result.failed += 1;
      }
    }
  }

  return result;
}
